INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21801, 'Zechariah 3:4', 'Zechariah', 3, 4, '&nbsp;فرښتې هغوئ ته وفرمائيل څوک چې د هغۀ د وړاندې ولاړ وُو، ”د دۀ نه ګنده جامې وباسئ.“ بيا هغې يشوَع ته وفرمائيل، ”وګوره، ما ستا ګناهونه لرې کړل، او زۀ به تا ته ښائسته جامې درواغوندم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21802, 'Zechariah 3:5', 'Zechariah', 3, 5, '&nbsp;بيا ما ووئيل، ”هغوئ دې د هغۀ په سر باندې يو پاک پټکے کېږدى،“ او هغوئ ورته پاک پټکے په سر کېښودو او ښکلې نوې جامې يې ورواغوستلې کله چې لا د مالِک خُدائ فرښته د هغۀ سره هلته ولاړه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21803, 'Zechariah 3:6', 'Zechariah', 3, 6, '&nbsp;د مالِک خُدائ فرښتې يشوَع له په کلکه وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21804, 'Zechariah 3:7', 'Zechariah', 3, 7, '&nbsp;”دا هغه څۀ دى چې مالِک خُدائ ربُ الافواج فرمائى، کۀ تۀ زما په لار روان يې او زما قانون منې، نو تۀ به زما د کور حکمرانى کوې او زما د دربار اختيار به درسره وى، او زۀ به تا له د دوئ په مينځ کښې ځائ درکړم څوک چې دلته ولاړ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21805, 'Zechariah 3:8', 'Zechariah', 3, 8, '&nbsp;واوره، اے مشر اِمامه يشوَع او نور اِمامان چې ستا په وړاندې ناست دى، تاسو د راتلونکى ښۀ وخت نښه يئ، زۀ به خپل خِدمت کوونکے راولم چې څانګه بللے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21806, 'Zechariah 3:9', 'Zechariah', 3, 9, '&nbsp;وګورئ، هغه قيمتى کاڼے چې ما د يشوَع په وړاندې اېښے دے. د هغه کاڼى اووۀ مخونه دى، او زۀ به په دې نقش وليکم، مالِک خُدائ ربُ الافواج فرمائى، او زۀ به د دې مُلک ګناهونه په يوه ورځ کښې ختم کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21807, 'Zechariah 3:10', 'Zechariah', 3, 10, '&nbsp;په هغه ورځ به تاسو هر يو کس خپل ګاونډى راوغواړئ چې خپل د انګورو او اينځر د ونې لاندې کښېنئ، مالِک خُدائ ربُ الافواج فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21808, 'Zechariah 4:1', 'Zechariah', 4, 1, '&nbsp;بيا کومې فرښتې چې ما سره خبرې کولې ما له بيا راغله او زۀ يې بېدار کړم، لکه څنګه چې يو سړے د خوب نه راپاڅوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21809, 'Zechariah 4:2', 'Zechariah', 4, 2, '&nbsp;”اوس تا ته څۀ ښکارى؟“ هغې ما نه تپوس وکړو. ما جواب ورکړو، ”زۀ د سرو زرو يو ډيوټ ګورم چې په سر يې د تېلو يوه کاسه ده. او د کاسې نه ګېرچاپېره اووۀ ډيوې دى، او د هرې يوې د باتو سره اووۀ د تېلو فوارې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21810, 'Zechariah 4:3', 'Zechariah', 4, 3, '&nbsp;هم دې سره خوا ته دوه د زيتُونو ونې دى، يو د جام ښى طرف ته او بله ګس طرف ته ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21811, 'Zechariah 4:4', 'Zechariah', 4, 4, '&nbsp;ما د فرښتې نه تپوس وکړو چا چې ما سره خبرې کولې، ”دا څۀ دى، زما مالِکه؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21812, 'Zechariah 4:5', 'Zechariah', 4, 5, '&nbsp;هغې ما ته جواب راکړو، ”آيا تا ته پته نشته چې دا څۀ دى؟“ ”نه، زما مالِکه،“ ما جواب ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21813, 'Zechariah 4:6', 'Zechariah', 4, 6, '&nbsp;نو هغه فرښتې ما ته وفرمائيل، ”دا زرُبابل ته د مالِک خُدائ کلام دے، نۀ په طاقت او نۀ په قدرت، خو زما په روح باندې، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21814, 'Zechariah 4:7', 'Zechariah', 4, 7, '&nbsp;هيڅ څيز هم نه، تر دې چې د زرُبابل په لار کښې غټ غرونه هم نۀ شى ودرېدلے، دا به د هغۀ په وړاندې هوار کړے شى. او کله چې زرُبابل د خُدائ د کور آخرى کاڼے په خپل ځائ کښې ږدى، خلق به چغې ووهى، خُدائ دې برکت ورکړى. خُدائ دې برکت ورکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21815, 'Zechariah 4:8', 'Zechariah', 4, 8, '&nbsp;بيا د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21816, 'Zechariah 4:9', 'Zechariah', 4, 9, '&nbsp;”د زرُبابل لاسونو د خُدائ د کور بنياد کېښودو، هم د دۀ لاسونه به يې مکمل کړى. بيا به تاسو ته پته ولګى چې مالِک خُدائ ربُ الافواج زۀ تاسو ته رالېږلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21817, 'Zechariah 4:10', 'Zechariah', 4, 10, '&nbsp;وړو شروعاتو ته په سپکه سترګه مۀ ګورئ، ځکه چې هغه د کار په شروع کېدو سره چې د زرُبابل په لاس کښې سال وګورى خوشحاليږى. دا اووۀ ډيوې د مالِک خُدائ د سترګو نمائندګى کوى، چې د هغوئ په ذريعه د ټولې دُنيا لټون کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21818, 'Zechariah 4:11', 'Zechariah', 4, 11, '&nbsp;بيا ما د فرښتې نه تپوس وکړو، ”دا د زيتُونو دوه ونې څۀ دى چې د ډيوټ ښې او ګس طرف ته دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21819, 'Zechariah 4:12', 'Zechariah', 4, 12, '&nbsp;او بيا ما هغې نه تپوس وکړو، ”دا دوه د زيتُونو څانګې چې د سرو زرو دوه نلکو په خوا کښې دى چې ترې تېل بهيږى دا څۀ دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21820, 'Zechariah 4:13', 'Zechariah', 4, 13, '&nbsp;هغې جواب راکړو، ”آيا تا ته پته نشته چې دا څۀ دى؟“ ”نه، مالِکه،“ ما ورته ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21821, 'Zechariah 4:14', 'Zechariah', 4, 14, '&nbsp;نو هغې وفرمائيل، ”دا دوه غوره شوى سړى دى چې د ټولې دُنيا د مالِک خِدمت وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21822, 'Zechariah 5:1', 'Zechariah', 5, 1, '&nbsp;ما بيا وکتل، هلته په هوا کښې زما په وړاندې يو کولاو شوے طومار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21823, 'Zechariah 5:2', 'Zechariah', 5, 2, '&nbsp;نو فرښتې زما نه تپوس وکړو چې، ”تا ته څۀ ښکارى؟“ ما جواب ورکړو چې، ”ما ته په هوا کښې يو کولاو طومار ښکارى چې لس ګزه اوږد او پينځۀ ګزه پلن دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21824, 'Zechariah 5:3', 'Zechariah', 5, 3, '&nbsp;او هغې ما ته وفرمائيل، ”دا هغه لعنت دے چې په ټوله دُنيا کښې به راشى، ځکه څۀ چې د دۀ په يو اړخ کښې ليکلے شوى دى د هغې په مطابق، هر يو غل به وشړلے شى، او څۀ چې د دې په بل اړخ ليکلے شوى دى د هغې په مطابق، هر څوک چې د دروغو قسمونه خورى هغوئ به لرې کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21825, 'Zechariah 5:4', 'Zechariah', 5, 4, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى، زۀ به دا لعنت بهر ولېږم، او دا به د غل کور ته او د هغه چا کور ته ورننوځى څوک چې زما په نوم د دروغو قسمونه خورى. دا به په هغه کور کښې پاتې شى او دا به د دې لرګى او کاڼى دواړه په پوره توګه تباه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21826, 'Zechariah 5:5', 'Zechariah', 5, 5, '&nbsp;بيا هغه فرښته چې ما سره يې خبرې کولې ما ته نزدې راغله او ما ته يې وفرمائيل، ”بره وګوره او هغه څۀ چې ښکارى دا څۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21827, 'Zechariah 5:6', 'Zechariah', 5, 6, '&nbsp;ما ترې تپوس وکړو چې، ”دا څۀ دى؟“ هغې جواب راکړو، ”دا د پېمانې ټوکرۍ ده.“ او هغې دا وفرمائيل چې، ”چې د ټول مُلک د خلقو د بې‌اِنصافۍ نه ډکه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21828, 'Zechariah 5:7', 'Zechariah', 5, 7, '&nbsp;بيا د سيکې دروند سر د ټوکرۍ نه اوچت کړے شو، او په ټوکرۍ کښې يوه ښځه ناسته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21829, 'Zechariah 5:8', 'Zechariah', 5, 8, '&nbsp;فرښتې وفرمائيل، ”د دې ښځې نامه بدعملى ده،“ او هغې هغه په ټوکرۍ کښې بيا ورديکه کړه او د سيکې دروند سر يې پرې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21830, 'Zechariah 5:9', 'Zechariah', 5, 9, '&nbsp;بيا ما بره وکتل، او زما په وړاندې دوه ښځې وې، چې وزرې يې په هوا کښې وې. د هغوئ وزرې لکه د زاڼې د وزرې په شان وې، او هغوئ دا ټوکرۍ د زمکې نه آسمان ته وخېژوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21831, 'Zechariah 5:10', 'Zechariah', 5, 10, '&nbsp;”هغوئ دا ټوکرۍ چرته وړى؟“ ما د هغه فرښتې نه چې ما سره يې خبرې کولې تپوس وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21832, 'Zechariah 5:11', 'Zechariah', 5, 11, '&nbsp;هغې جواب راکړو چې، ”د بابل مُلک ته چې د هغې دپاره هلته يو کور تيار کړى. کله چې هغه تيار شى، نو هلته به ټوکرۍ په خپل ځائ کېښودے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21833, 'Zechariah 6:1', 'Zechariah', 6, 1, '&nbsp;ما بيا بره وکتل، او هلته زما په وړاندې څلور جنګى ګاډۍ د پيتلو د دوو غرونو د مينځ نه راروانې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21834, 'Zechariah 6:2', 'Zechariah', 6, 2, '&nbsp;وړومبۍ ګاډۍ کښې سرۀ آسونه، دوېمه کښې تور آسونه وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21835, 'Zechariah 6:3', 'Zechariah', 6, 3, '&nbsp;درېمه کښې سپين آسونه او څلورمه کښې برَګ آسونه وُو، ټول ډېر مضبوط وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21836, 'Zechariah 6:4', 'Zechariah', 6, 4, '&nbsp;ما د هغه فرښتې نه تپوس وکړو چا چې ما سره خبرې کولې، ”دا څۀ دى زما مالِکه؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21837, 'Zechariah 6:5', 'Zechariah', 6, 5, '&nbsp;فرښتې راله جواب راکړو، ”دا د آسمان څلور روحونه دى، دا د ټولې دُنيا د مالِک خُدائ د حضور نه بهر راوتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21838, 'Zechariah 6:6', 'Zechariah', 6, 6, '&nbsp;هغه ګاډۍ چې تور آسونه يې دى د شمال مُلک طرف ته، د سپينو آسونو والا د مغرب طرف ته، او د برَګو آسونو والا د جنوب طرف ته روانه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21839, 'Zechariah 6:7', 'Zechariah', 6, 7, '&nbsp;کله چې هغه طاقتور آسونه بهر ووتل، نو هغوئ د دُنيا د ګشت لګولو دپاره بې‌صبره وُو. او هغې وفرمائيل، ”لاړ شئ او په دُنيا کښې ګشت ولګوئ.“ نو هغوئ د دُنيا د ګشت لګولو دپاره لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21840, 'Zechariah 6:8', 'Zechariah', 6, 8, '&nbsp;بيا هغې ما ته آواز وکړو چې، ”ګوره، کوم آسونه چې د شمال طرف ته روان دى هغوئ زما غصه په شمال مُلک کښې سړه کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21841, 'Zechariah 6:9', 'Zechariah', 6, 9, '&nbsp;بيا د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21842, 'Zechariah 6:10', 'Zechariah', 6, 10, '&nbsp;”د جلاوطن کړے شوى خلدى، طوبياه او يدعياه نه سپين زر او سرۀ زر واخله، څوک چې د بابل نه راغلى دى. هم په هغه ورځ د يوسياه د صفنياه د زوئ کور ته لاړ شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21843, 'Zechariah 6:11', 'Zechariah', 6, 11, '&nbsp;د هغوئ د سپينو زرو او سرو زرو تحفه واخله او تاج ترې جوړ کړه، او دا د مشر اِمام د يهوصدق د زوئ يشوَع په سر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21844, 'Zechariah 6:12', 'Zechariah', 6, 12, '&nbsp;هغۀ ته ووايه چې، مالِک خُدائ ربُ الافواج دا فرمائى، ”دا هغه سړے دے د چا نوم چې څانګه ده، او دے به د خپل ځان نه څانګې خورې کړى او د مالِک خُدائ کور به جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21845, 'Zechariah 6:13', 'Zechariah', 6, 13, '&nbsp;دا هغه څوک دے چې د مالِک خُدائ کور به جوړ کړى او دۀ ته به د بادشاهۍ جامې ورواغوستے شى او په تخت به کښېنى او بادشاهى به کوى. او په خوا کښې به اِمام د دۀ تخت سره ولاړ وى. او د دواړو په مينځ کښې به جوړ توړ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21846, 'Zechariah 6:14', 'Zechariah', 6, 14, '&nbsp;د خلدى، طوبياه، يدعياه او حين د صفنياه زوئ ته به تاج د مالِک خُدائ په کور کښې د يادګار په توګه ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21847, 'Zechariah 6:15', 'Zechariah', 6, 15, '&nbsp;هغه څوک چې لرې دى هغوئ به راشى او د مالِک خُدائ د کور په جوړولو کښې به مدد وکړى. او تاسو ته به پته ولګى چې مالِک خُدائ ربُ الافواج زۀ تاسو ته رالېږلے يم. دا به وشى خو چې تاسو د مالِک خُدائ د خپل خُدائ پاک پوره تابعدارى وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21848, 'Zechariah 7:1', 'Zechariah', 7, 1, '&nbsp;د داريوس د سلطنت په څلورم کال، د مالِک خُدائ کلام په زکرياه نازل شو د نهمې مياشتې په څلورمه ورځ د کِسليو په مياشت کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21849, 'Zechariah 7:2', 'Zechariah', 7, 2, '&nbsp;د بيت‌ايل خلقو شراضر او رجم‌مِلک سره د خپلو سړو ولېږل، چې مالِک خُدائ ته زارى وکړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21850, 'Zechariah 7:3', 'Zechariah', 7, 3, '&nbsp;چې د مالِک خُدائ ربُ الافواج د کور د اِمامانو او پېغمبرانو نه تپوس وکړى چې، ”آيا مونږ ماتم وکړُو او روژه ونيسو په پينځمه مياشت کښې، لکه څنګه چې مونږ دا د ډېرو کالونو نه کوُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21851, 'Zechariah 7:4', 'Zechariah', 7, 4, '&nbsp;بيا د مالِک خُدائ ربُ الافواج کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21852, 'Zechariah 7:5', 'Zechariah', 7, 5, '&nbsp;”د دې مُلک د ټولو خلقو نه او اِمامانو نه پوښتنه وکړه، کله چې تاسو روژه نيوله او ماتم مو په پينځمه او اوومه مياشت کښې د تېرو اويا کالو راسې کولو، آيا دا روژې په حقيقت تاسو زما دپاره نيولې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21853, 'Zechariah 7:6', 'Zechariah', 7, 6, '&nbsp;او کله چې تاسو خوراک څښاک کولو، آيا دا تاسو د ځان دپاره نۀ کولو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21854, 'Zechariah 7:7', 'Zechariah', 7, 7, '&nbsp;آيا دا هغه کلام نۀ دے چې ما مالِک خُدائ فرمائيلى وُو د وړومبيو پېغمبرانو په ذريعه کله چې په يروشلم او د دې نه ګېرچاپېره کلو کښې سکون او برکت وو، او نجب او د مغربى غرونو لمنې ښۀ آبادې وې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21855, 'Zechariah 7:8', 'Zechariah', 7, 8, '&nbsp;او د مالِک خُدائ ربُ الافواج کلام بيا په زکرياه نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21856, 'Zechariah 7:9', 'Zechariah', 7, 9, '&nbsp;”دا مالِک خُدائ ربُ الافواج فرمائى، په رښتيا سره اِنصاف کوئ، يو بل سره رحم او مينه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21857, 'Zechariah 7:10', 'Zechariah', 7, 10, '&nbsp;په کونډو، يتيمانو، په پردو او غريبانانو ظلم زياتے مۀ کوئ. په خپلو زړونو کښې يو بل ته شېطانى سوچونه مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21858, 'Zechariah 7:11', 'Zechariah', 7, 11, '&nbsp;خو هغوئ په دې غور کولو نه اِنکار وکړو، او په سرکشۍ سره يې ورته شا کړه او خپل غوږونه يې بند کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21859, 'Zechariah 7:12', 'Zechariah', 7, 12, '&nbsp;هغوئ خپل زړونه لکه د هيرې سخت کاڼى په شان سخت کړل او هغوئ هغه حکمونو يا تعليماتو ته توجو نۀ ورکوله چې مالِک خُدائ ربُ الافواج د خپل روح نه د پخوانو پېغمبرانو په ذريعه رالېږلى وُو، نو په دې وجه مالِک خُدائ ربُ الافواج سخت په قهر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21860, 'Zechariah 7:13', 'Zechariah', 7, 13, '&nbsp;کله چې ما ورته آواز وکړو، نو هغوئ نۀ اورېدلو، او نو اوس کله چې هغوئ آواز وکړى، نو زۀ به يې نۀ اورم، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21861, 'Zechariah 7:14', 'Zechariah', 7, 14, '&nbsp;ما هغوئ د طوفان په ذريعه په لرى قومونو کښې خوارۀ وارۀ کړل، چرته چې هغوئ لکه د پردو په شان اوسېدل. د هغوئ مُلک وران ويجاړ پروت وُو او د هغوئ نه پس ورته څوک نۀ شو راتلے. نو دغه شان د هغوئ خپل ښکلے مُلک په صحرا بدل شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21862, 'Zechariah 8:1', 'Zechariah', 8, 1, '&nbsp;بيا د مالِک خُدائ ربُ الافواج کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21863, 'Zechariah 8:2', 'Zechariah', 8, 2, '&nbsp;مالِک خُدائ ربُ الافواج دا فرمائى چې، ”زۀ په يروشلم ډېر زيات غېرت کوم، زۀ د هغې دپاره سوزېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21864, 'Zechariah 8:3', 'Zechariah', 8, 3, '&nbsp;مالِک خُدائ دا فرمائى چې، ”زۀ به صيون ته راواپس شم او په يروشلم کښې به اوسېږم. بيا به يروشلم وفادار ښار بللے شى، او د مالِک خُدائ ربُ الافواج غر به مقدس غر بللے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21865, 'Zechariah 8:4', 'Zechariah', 8, 4, '&nbsp;مالِک خُدائ ربُ الافواج دا فرمائى، ”يو ځل بيا به زاړۀ سړى او ښځې د يروشلم په کوڅو کښې کښېنى، هر يو سره به د بوډاتوب په وجه په لاس کښې کونټۍ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
